public class Student {
    private String name;
    private int age;
    private double gpa;
    public Student(String name, int age, double gpa) {
        setName(name); setAge(age); setGpa(gpa);
    }
    public String getName() { return name; }
    public void setName(String name) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("Name cannot be blank");
        this.name = name.trim();
    }
    public int getAge() { return age; }
    public void setAge(int age) {
        if (age < 0 || age > 150) throw new IllegalArgumentException("Invalid age: " + age);
        this.age = age;
    }
    public double getGpa() { return gpa; }
    public void setGpa(double gpa) {
        if (gpa < 0.0 || gpa > 10.0) throw new IllegalArgumentException("GPA must be between 0 and 10");
        this.gpa = gpa;
    }
    @Override public String toString() { return String.format("Student{name='%s', age=%d, gpa=%.1f}", name, age, gpa); }
}

