public class User {
    private final String name;
    private final String email;
    private final String phone;
    private final int age;
    private final String role;
    private User(Builder b) {
        this.name = b.name; this.email = b.email; this.phone = b.phone;
        this.age = b.age; this.role = b.role;
    }
    public static class Builder {
        private final String name;
        private final String email;
        private String phone = null;
        private int age = 0;
        private String role = "USER";
        public Builder(String name, String email) {
            if (name == null || email == null) throw new IllegalArgumentException();
            this.name = name; this.email = email;
        }
        public Builder phone(String p) { this.phone = p; return this; }
        public Builder age(int a) { this.age = a; return this; }
        public Builder role(String r) { this.role = r; return this; }
        public User build() { return new User(this); }
    }
    @Override public String toString() { return String.format("User{name='%s', role='%s'}", name, role); }
}
// Usage: User u = new User.Builder("Raj", "raj@mail.com").age(25).role("ADMIN").build();

