public record Coordinate(double lat, double lon) {
    Coordinate {
        if (lat < -90 || lat > 90)
            throw new IllegalArgumentException("Latitude must be between -90 and 90, got: " + lat);
        if (lon < -180 || lon > 180)
            throw new IllegalArgumentException("Longitude must be between -180 and 180, got: " + lon);
    }
    // Optional: custom convenience method
    public double distanceTo(Coordinate other) {
        double dLat = Math.toRadians(other.lat - this.lat);
        double dLon = Math.toRadians(other.lon - this.lon);
        return Math.sqrt(dLat * dLat + dLon * dLon); // simplified
    }
}
// Everything else (accessors lat(), lon(), equals(), hashCode(), toString()) auto-generated by Record.
